import numpy as np, time
np.random.seed(0)
ul=np.linalg._umath_linalg
n=10
A=np.random.normal(size=(n,n)).astype(np.float64)
funcs={
 'np.eig':lambda: np.linalg.eig(A),
 'ul.eig(A)':lambda: ul.eig(A),
 'ul.eig no_sig':lambda: ul.eig(A, signature=None),
 'ul.eig (m,m)':lambda: ul.eig(A, signature='(m,m)->(m),(m,m)'),
}
for name,fn in funcs.items():
    try:
        out=fn(); print(name, type(out), [getattr(x,'dtype',None) for x in out] if isinstance(out,tuple) else out.dtype)
        fn(); reps=5000; t=time.perf_counter()
        for _ in range(reps): fn()
        print(' %.3f us'%((time.perf_counter()-t)/reps*1e6))
    except Exception as e: print(name,'ERROR',repr(e))
# out params
V=np.empty(n, dtype=np.complex128); W=np.empty((n,n), dtype=np.complex128)
for cast in ['same_kind','unsafe']:
    try:
      def f():
        return ul.eig(A,out=(V,W), casting=cast)
      r=f(); print('out',cast,type(r), V[:2], W.shape)
      reps=5000; t=time.perf_counter()
      for _ in range(reps): f()
      print(' %.3f us'%((time.perf_counter()-t)/reps*1e6))
    except Exception as e: print('out',cast,'ERROR',repr(e))
